    var ed = safe2Dist(p.extinguisher, SAFE2_STATION);
    rules.push({ id: 'extinguisher', dist: ed, ok: ed <= SAFE2_RADIUS_FT });
    var fd = safe2Dist(p.fireWatch, SAFE2_STATION);
    rules.push({ id: 'fireWatch', dist: fd, ok: fd >= 5 && fd <= SAFE2_RADIUS_FT });
    var xd = safe2Dist(p.extractor, SAFE2_STATION);
