    '3':  { gas: false, pol: 'dcep', pass: 'single' },
    '4':  { gas: false, pol: 'dcep', pass: 'multi' },
    '5':  { gas: true,  pol: 'dcep', pass: 'multi' },
    '6':  { gas: false, pol: 'dcep', pass: 'multi' },
    '7':  { gas: false, pol: 'dcen', pass: 'multi' },
    '8':  { gas: false, pol: 'dcen', pass: 'multi' },
    '9':  { gas: true,  pol: 'dcep', pass: 'multi' },
    '10': { gas: false, pol: 'dcen', pass: 'single' },
    '11': { gas: false, pol: 'dcen', pass: 'multi' },
    '12': { gas: true,  pol: 'dcep', pass: 'multi' },
    '13': { gas: false, pol: 'dcen', pass: 'single' },
    '14': { gas: false, pol: 'dcen', pass: 'single' },
