      if (m[4]) parts.push({ seg: m[4], role: 'gas', value: m[4] });
      if (m[5]) parts.push({ seg: 'J', role: 'impact' });
      if (m[6]) parts.push({ seg: m[6], role: 'hydrogen', value: parseInt(m[6].slice(1), 10) });
